#include "amity/consortium/enrollment.hpp"
#include <algorithm>
#include "amity/consortium/hostname.hpp"
namespace amity::consortium {
namespace {
std::string hex(std::string_view input){std::string out;for(unsigned char b:input){out+="0123456789abcdef"[b>>4];out+="0123456789abcdef"[b&15];}return out;}
bool unhex(const Json *input,std::string &out){if(!input||input->type!=Json::Type::string||input->string.empty()||input->string.size()>2048||input->string.size()%2)return false;out.clear();auto d=[](char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1;};for(size_t n=0;n<input->string.size();n+=2){int a=d(input->string[n]),b=d(input->string[n+1]);if(a<0||b<0)return false;out+=char(a*16+b);}return true;}
bool pin(std::string_view value){return value.size()==64&&std::all_of(value.begin(),value.end(),[](char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f');});}
bool valid(const JoinProposal&p){return valid_hostname(p.candidate_hostname)&&p.join_id&&p.consortium_id&&p.coordinator_id&&p.candidate_id&&p.candidate_id!=p.coordinator_id&&p.epoch==1&&p.revision&&!p.coordinator_leaf.empty()&&p.coordinator_leaf.size()<=1024&&!p.candidate_leaf.empty()&&p.candidate_leaf.size()<=1024&&pin(p.coordinator_pin)&&pin(p.candidate_pin)&&p.coordinator_pin!=p.candidate_pin&&!p.host.empty()&&p.host.size()<=64&&std::all_of(p.host.begin(),p.host.end(),[](unsigned char c){return(c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='.'||c=='-';});}
}
std::string encode_join_proposal(const JoinProposal&p){if(!valid(p))return {};return "{\"bootstrap_profile\":2,\"candidate_hostname\":\""+p.candidate_hostname+"\",\"candidate_id\":\""+p.candidate_id.str()+"\",\"candidate_leaf\":\""+hex(p.candidate_leaf)+"\",\"candidate_pin\":\""+p.candidate_pin+"\",\"consortium_id\":\""+p.consortium_id.str()+"\",\"coordinator_id\":\""+p.coordinator_id.str()+"\",\"coordinator_leaf\":\""+hex(p.coordinator_leaf)+"\",\"coordinator_pin\":\""+p.coordinator_pin+"\",\"epoch\":\""+std::to_string(p.epoch)+"\",\"host\":\""+p.host+"\",\"join_id\":\""+p.join_id.str()+"\",\"protocol_max\":1,\"protocol_min\":1,\"revision\":\""+std::to_string(p.revision)+"\",\"role\":\"actuator\"}";}
bool decode_join_proposal(std::string_view bytes,JoinProposal &out){Json v;JsonError error;JoinProposal p;uint64_t profile=0,low=0,high=0;if(!parse_json(bytes,v,error,6144)||!closed(v,{"bootstrap_profile","candidate_hostname","candidate_id","candidate_leaf","candidate_pin","consortium_id","coordinator_id","coordinator_leaf","coordinator_pin","epoch","host","join_id","protocol_max","protocol_min","revision","role"})||!json_uint(v.get("bootstrap_profile"),profile,2,2)||!json_uint(v.get("protocol_min"),low,1,1)||!json_uint(v.get("protocol_max"),high,1,1)||!v.get("role")||v.get("role")->type!=Json::Type::string||v.get("role")->string!="actuator"||!id(v.get("join_id"),p.join_id)||!id(v.get("consortium_id"),p.consortium_id)||!id(v.get("coordinator_id"),p.coordinator_id)||!id(v.get("candidate_id"),p.candidate_id)||!decimal(v.get("epoch"),p.epoch)||!decimal(v.get("revision"),p.revision)||!unhex(v.get("coordinator_leaf"),p.coordinator_leaf)||!unhex(v.get("candidate_leaf"),p.candidate_leaf)||!json_string(v.get("coordinator_pin"),p.coordinator_pin,64,64)||!json_string(v.get("candidate_pin"),p.candidate_pin,64,64)||!json_string(v.get("host"),p.host,1,64)||!json_string(v.get("candidate_hostname"),p.candidate_hostname,1,32)||!valid(p)||encode_join_proposal(p)!=bytes)return false;out=std::move(p);return true;}
}
